 if(mode==='history'){const months=[0,1,2].map(n=>{const d=new Date();d.setMonth(d.getMonth()-n);return d.toISOString().slice(0,7)}),rows=mine.filter(o=>(o.created_at||'').slice(0,7)===courierHistoryMonth);return `<div class="courier-period">${months.map(v=>`<button data-history-month="${v}" class="${v===courierHistoryMonth?'active':''}">${new Date(v+'-02').toLocaleDateString('pt-BR',{month:'long'})}</button>`).join('')}</div>${rows.length?rows.map(o=>courierOrderCard(o).replace('<article class="courier-list-card"',`<article class="courier-list-card" data-history-order="${esc(o.id)}"`)).join(''):'<div class="courier-empty"><b>Nenhuma entrega no per\u00edodo</b></div>'}`}
